def solve(nums):
    # nums가 주어진 범위 내의 정수만 포함하는지 확인합니다.
    # 그리고, nums가 비어 있는 경우 예외적으로 처리합니다.
    # 리스트의 크기는 리스트의 중앙값(Midian)을 달성할 수 있도록 설정합니다.
    if len(nums) == 0:
        return None

    # 중앙값을 찾기 위해 시간 복잡도를 줄이기 위해 다른 방법을 사용합니다.
    nums.sort()

    # 발견되지 않은 정수를 찾습니다.
    for i in range(len(nums)):
        # 누락된 숫자를 찾았을 때 그 번호를 반환합니다.
        if i != nums[i]:
            return i
    # 모든 숫자가 존재한다면 제일 큰 숫자+1을 반환합니다.
    return len(nums)

