def solve(x):
    if x < 2:
        return x
    left, right = 2, x // 2
    while left <= right:
        mid = (left + right) // 2
        mid_sq = mid * mid
        if mid_sq == x:
            return mid
        elif mid_sq < x:
            left = mid + 1
        else:
            right = mid - 1
    return right

